<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3';
import { ref, onUnmounted, computed } from 'vue';
import { useExamContext } from '../../exam-context';
import ConfirmAction from '../../Components/ConfirmAction.vue';
import AppIcon from '../../Components/AppIcon.vue';
import CandidateLayout from '../../Layouts/CandidateLayout.vue';
const props = defineProps({ accesses: Array, attempts: Array, today: String, server_time: String });
const offset = Date.parse(props.server_time) - Date.now();
const {context,candidateBase}=useExamContext(); const action=ref(null);
const clock = ref(Date.now() + offset);
const timer = setInterval(() => clock.value = Date.now() + offset, 1000);
onUnmounted(() => clearInterval(timer));
const start = useForm({});
const active = access => props.attempts.find(attempt => attempt.exam_access_id === access.id && !attempt.submitted_at && Date.parse(attempt.expires_at) > clock.value);
function available(access) { return access.is_active && access.exam.status === 'published' && clock.value >= Date.parse(access.opens_at) && clock.value < Date.parse(access.closes_at); }
function status(access) { if (!access.is_active) return 'Quyền thi đã thu hồi'; if (access.exam.status !== 'published') return 'Đề thi tạm đóng'; if (clock.value < Date.parse(access.opens_at)) return 'Chưa đến giờ thi'; if (clock.value >= Date.parse(access.closes_at)) return 'Đã hết thời gian thi'; if (active(access)) return 'Đang làm bài'; if (access.attempts_count >= access.max_attempts) return 'Đã hết lượt'; return 'Sẵn sàng'; }
function begin(access) { if(active(access))return;action.value={method:'post',url:candidateBase.value+'/accesses/'+access.id+'/start',title:'Bắt đầu lượt thi mới',message:'Bắt đầu bài mới sẽ tính một lượt thi. Bạn đã sẵn sàng?',button:'Bắt đầu thi'}; }
function archived(access) { return !access.is_active || access.exam.status!=='published' || clock.value>=Date.parse(access.closes_at) || (!active(access)&&access.attempts_count>=access.max_attempts); }
const currentAccesses=computed(()=>props.accesses.filter(access=>!archived(access)));
const historyAccesses=computed(()=>props.accesses.filter(archived));
const historyAttempts=computed(()=>props.attempts.filter(attempt=>attempt.submitted_at||Date.parse(attempt.expires_at)<=clock.value||historyAccesses.value.some(access=>access.id===attempt.exam_access_id)));
const readyCount=computed(()=>props.accesses.filter(access=>available(access)&&(active(access)||access.attempts_count<access.max_attempts)).length);
const completedCount=computed(()=>props.attempts.filter(attempt=>attempt.submitted_at).length);
function resultLabel(attempt) {
 if(!attempt.submitted_at)return 'Xem bài thi →';
 if(!attempt.graded_at)return 'Chờ chấm';
 if(attempt.toeic_total_score!=null)return attempt.toeic_total_score+' / 990 · L: '+attempt.listening_result.scaled+' · R: '+attempt.reading_result.scaled;
 const sections=[['Listening',attempt.listening_result],['Reading',attempt.reading_result]].filter(([,result])=>result?.scaled!=null);
 return sections.length?sections.map(([name,result])=>name+': '+result.scaled+'/495').join(' · '):attempt.total_points+' điểm';
}
const date = value => new Intl.DateTimeFormat('vi-VN', { timeZone: 'Asia/Bangkok' }).format(new Date(value));
</script>
<template><Head title="Cổng thi" /><CandidateLayout><section class="candidate-welcome-banner"><div><div class="welcome-kicker">KHÔNG GIAN THÍ SINH · {{context.name.toUpperCase()}}</div><h1>Sẵn sàng thể hiện năng lực?</h1><p>Các bài thi {{context.name}} được cấp riêng cho bạn. Kiểm tra ngày, ca và số lượt trước khi bắt đầu.</p><span class="candidate-welcome-date"><AppIcon name="clock" :size="16"/>{{date(today)}} · Giờ Việt Nam</span></div><span class="candidate-welcome-icon" aria-hidden="true"><AppIcon :name="context.slug==='course'?'book':'graduation'" :size="64"/></span></section><div class="candidate-summary-strip"><div><span class="summary-icon"><AppIcon name="file"/></span><strong>{{currentAccesses.length}}</strong><span>Khóa thi hiện tại</span></div><div><span class="summary-icon"><AppIcon name="play"/></span><strong>{{readyCount}}</strong><span>Có thể vào thi</span></div><div><span class="summary-icon"><AppIcon name="check"/></span><strong>{{completedCount}}</strong><span>Lượt đã hoàn thành</span></div></div><div class="notice">Mỗi bài mới tính 1 lượt. Bạn có thể mở lại bài đang làm trong thời gian còn lại mà không mất thêm lượt. Hệ thống tự lưu đáp án khi bạn chọn.</div>
 <div v-if="!currentAccesses.length" class="card empty-state student-empty-state"><span class="student-empty-icon"><AppIcon name="book" :size="35"/></span><h2>Bạn chưa có khóa thi còn hiệu lực</h2><p>Liên hệ quản trị viên để được xếp vào khóa thi mới. Các khóa đã kết thúc được lưu ở lịch sử bên dưới.</p></div>
 <div class="candidate-exams"><article v-for="(access,index) in currentAccesses" :key="access.id" class="card candidate-exam-card" :style="{'--card-order':index}" :class="{'exam-ready':available(access)&&(active(access)||access.attempts_count<access.max_attempts)}"><div class="panel-title"><span class="pill">{{ access.access_mode === 'session' ? access.session_name : 'Thi theo ngày' }}</span><span class="muted">{{ access.exam.duration_minutes }} phút</span></div><p v-if="access.round" class="text-link">Đợt thi: {{access.round.name}}</p><h2 class="candidate-exam-title">{{ access.exam.title }}</h2><p class="muted">{{ access.exam.description || 'Bài thi được cấp riêng' }}</p><div class="info-row"><span>Ngày thi</span><strong>{{ date(access.exam_date) }}</strong></div><div v-if="access.access_mode === 'session'" class="info-row"><span>Khung giờ</span><strong>{{ access.start_time.slice(0,5) }}–{{ access.end_time.slice(0,5) }}</strong></div><div class="info-row"><span>Lượt đã dùng / tối đa</span><strong>{{ access.attempts_count }} / {{ access.max_attempts }}</strong></div><div class="info-row"><span>Trạng thái</span><span class="pill">{{ status(access) }}</span></div><div class="section-gap"><Link v-if="available(access) && active(access)" :href="`${candidateBase}/attempts/${active(access).id}`" class="btn">Tiếp tục bài đang làm →</Link><button v-else :disabled="start.processing || !available(access) || access.attempts_count >= access.max_attempts" @click="begin(access)">Bắt đầu thi</button></div></article></div>
 <section v-if="historyAccesses.length||historyAttempts.length" class="card section-gap"><h2>Lịch sử thi</h2><div v-if="historyAccesses.length" class="tablewrap"><table><thead><tr><th>Khóa thi</th><th>Đề thi</th><th>Ngày thi</th><th>Trạng thái</th><th>Lượt đã thi</th></tr></thead><tbody><tr v-for="access in historyAccesses" :key="access.id"><td>{{access.round?.name||'Thi theo ngày / ca'}}</td><td>{{access.exam.title}}</td><td>{{date(access.exam_date)}}</td><td>{{status(access)}}</td><td>{{access.attempts_count?access.attempts_count+' lượt':'Chưa thi'}}</td></tr></tbody></table></div><h3 v-if="historyAttempts.length" class="section-gap">Các lượt thi</h3><template v-if="historyAttempts.length"><div class="tablewrap"><table><thead><tr><th>Đề thi</th><th>Lượt</th><th>Ngày bắt đầu</th><th>Trạng thái</th><th>Kết quả</th></tr></thead><tbody><tr v-for="attempt in historyAttempts" :key="attempt.id"><td>{{ accesses.find(access => access.id === attempt.exam_access_id)?.exam.title }}</td><td>{{ attempt.attempt_number }}</td><td>{{ date(attempt.started_at) }}</td><td>{{ attempt.submitted_at ? 'Đã kết thúc' : Date.parse(attempt.expires_at) <= clock ? 'Hết thời gian' : 'Đang làm' }}</td><td><span v-if="!attempt.submitted_at&&Date.parse(attempt.expires_at)>clock">Khóa thi không còn hiệu lực</span><Link v-else :href="`${candidateBase}/attempts/${attempt.id}`" class="text-link">{{ resultLabel(attempt) }}</Link></td></tr></tbody></table></div><p class="info-copy">Trắc nghiệm được chấm tự động. Bài tự luận và bài nói sẽ có điểm sau khi giáo viên chấm.</p></template></section>
<ConfirmAction :action="action" @close="action=null"/></CandidateLayout></template>
